// Item stack quantity text: black digits with a 1px white outline so the count reads clearly on any
// item icon regardless of its colours (S.: "на стаках цифры количества чёрными с белой обводкой").
void drawCountBW(SpriteBatch& sb, const Font& font, float x, float y, float scale,
                 const std::string& s) {
    for (int dx = -1; dx <= 1; ++dx)
        for (int dy = -1; dy <= 1; ++dy)
            if (dx || dy)
                font.draw(sb, x + static_cast<float>(dx), y + static_cast<float>(dy), scale,
                          ui::rgba(255, 255, 255, 255), s);  // white outline
    font.draw(sb, x, y, scale, ui::rgba(0, 0, 0, 255), s);   // black fill
}

