// Basic spammed single-hit melee that classically has NO cast effect (just the hit) -> the neutral
// fallback skips them so they don't flash every swing. (S. can extend this blacklist.)
bool isBasicMeleeSkill(u16 id) {
    switch (id) {
        case 5:   // SM_BASH
        case 42:  // MC_MAMMONITE
        case 46:  // AC_DOUBLE (Double Strafe)
        case 150: // MC_CARTREVOLUTION
        case 219: // RG_BACKSTAP
        case 220: // RG_RAID
            return true;
        default: return false;
    }
}

// Skills that already have a dedicated coded burst in emitSkillBurst -> the element fallback must skip them.
bool isCodedBurstSkill(u16 id) {
    switch (id) {
        case 5: case 7: case 8: case 24: case 28: case 29: case 30: case 31: case 34: case 73: case 74:
        case 137: case 142: case 156: case 254: case 271: case 361: case 362: case 379: case 382:
            return true;
        default: return false;
    }
}

// The real exe elemental-property texture (data/texture/effect/i_p_<ELEMENT>.tga: the 火水風地暗聖 kanji)
// + a tint colour for the accompanying glow. Only FIRE/WATER/WIND/EARTH/DARK/SAINT ship a kanji; poison/
// ghost/undead reuse i_p_DARK with their own tint.
const char* elementFxTex(u8 el, float& r, float& g, float& b) {
    switch (el) {
        case 1: r = 0.45f; g = 0.7f;  b = 1.0f;  return "i_p_WATER.tga";  // water: blue
        case 2: r = 0.7f;  g = 0.5f;  b = 0.3f;  return "i_p_EARTH.tga";  // earth: brown
        case 3: r = 1.0f;  g = 0.5f;  b = 0.2f;  return "i_p_FIRE.tga";   // fire: orange
        case 4: r = 0.6f;  g = 1.0f;  b = 0.7f;  return "i_p_WIND.tga";   // wind: green
        case 5: r = 0.7f;  g = 0.4f;  b = 0.9f;  return "i_p_DARK.tga";   // poison: purple
        case 6: r = 1.0f;  g = 1.0f;  b = 0.8f;  return "i_p_SAINT.tga";  // holy: pale gold
        case 7: r = 0.6f;  g = 0.35f; b = 0.8f;  return "i_p_DARK.tga";   // dark: violet
        case 8: r = 0.7f;  g = 0.8f;  b = 1.0f;  return "i_p_DARK.tga";   // ghost: pale blue
        case 9: r = 0.6f;  g = 0.9f;  b = 0.6f;  return "i_p_DARK.tga";   // undead: sickly green
        default: return nullptr;
    }
}

// Diagnostic (S.: "подключай все скиллы, будем получать от тестеров инфу что не так"): log the
// visual mapping the first time each skill id is cast, so a tester's "skill X shows nothing" maps
// straight to a wiring gap. Prints the skill id + whether a classic .str effect is bound (or NONE)
// + a RoM binding flag. One line per distinct skill id per session. `where` names the packet path.
void logSkillCastFx(u16 id, bool romBound, const char* where) {
    static std::unordered_set<u16> seen;
    if (!seen.insert(id).second) return;
    const SkillFxDef fx = skillFxDef(id);
    const char* str = fx.str ? fx.str : "-";
    log::info("skill-fx: id={} chan={} str={} ground={} rom={}", id, where, str,
              fx.ground ? 1 : 0, romBound ? 1 : 0);
}
// EFFECTID -> .str effect, extracted from the original uaRO.exe CEffect::Initialize dispatch
// (0x5c2630; see Client/docs/effect-ids-from-exe.md). The server plays these via
// ZC_NOTIFY_EFFECT2 (0x1f3) / clif_specialeffect(bl, EFFECTID, AREA) -- 31 call sites covering
// cooking, refine, taming, food buffs, status visuals etc. that the skill-cast path never sees.
// Returns the .str basename (data/texture/effect/<name>.str) or nullptr for coded/particle
// effects (the exe default case, e.g. warp 421/423) and the %d-animated / euc-kr-named entries,
// which need a dedicated multi-frame / Korean-path loader and are intentionally skipped here.
// Sprite colour multiplier from body/health ailments, matching the original client
// (roBrowser EntityState.effectColor = bodyState * healthState). opt1 is a body-state
// VALUE (stone/freeze/stun/sleep); opt2 is a health-state BITMASK (poison/curse/...).
// Petrify greys the sprite out, freeze dyes it ice-blue, poison purples it, curse darkens
// it to a dried blood-red. Multiplied into the actor's environment light at draw time.
Vec3 applyStatusTint(Vec3 c, u16 opt1, u16 opt2) {
    switch (opt1) {                 // OPT1_* (a value, not a mask)
        case 1: c.x *= 0.1f; c.y *= 0.1f; c.z *= 0.1f; break;   // STONE (petrified)
        case 6: c.x *= 0.3f; c.y *= 0.3f; c.z *= 0.3f; break;   // STONEWAIT (petrifying)
        case 2: c.x *= 0.0f; c.y *= 0.4f; c.z *= 0.8f; break;   // FREEZE (ice-blue)
        default: break;
    }
    if (opt2 & 0x0002) { c.x *= 0.50f; c.y *= 0.15f; c.z *= 0.10f; }  // OPT2_CURSE (dark red)
    if (opt2 & 0x0001) { c.x *= 0.90f; c.y *= 0.40f; c.z *= 0.80f; }  // OPT2_POISON (purple)
    return c;
}

// LK_AURABLADE (SI_AURABLADE 103): S. 2026-07-17 wants the char's SPRITE to take a yellowish/gold cast
// while the buff is active (NOT a status icon). Warm the light (boost R/G, drop B) so the whole sprite
// reads gold. Driven by the status on/off packet (0x196), so it lasts exactly the server's aura duration.
Vec3 applyAuraBladeTint(Vec3 c, bool active) {
    if (active) { c.x *= 1.2f; c.y *= 1.08f; c.z *= 0.5f; }
    return c;
}

// LK_CONCENTRATION (SI_CONCENTRATION 105): S. 2026-07-19 "лк-концентрейшен должна менять цвет спрайта
// как аура блейд" -- same sprite-recolour treatment as Aura Blade, but the classic Concentration RED
// body cast (boost R, drop G/B). Driven by the 0x196 status on/off so it lasts the buff's duration.
Vec3 applyConcentrationTint(Vec3 c, bool active) {
    if (active) { c.x *= 1.3f; c.y *= 0.5f; c.z *= 0.5f; }
    return c;
}

// #147 combat visual port (from the exe): a unit flashes brighter (toward white) for a split second the
// instant it takes damage -- the classic RO "hit flash". Boost the sprite's env light for ~0.1s after
// hurtStart. base is the already-computed light; returns it scaled up during the flash window.
Vec3 hitFlashLight(Vec3 base, double hurtStart, double now) {
    constexpr double kFlash = 0.11;  // seconds
    if (hurtStart <= 0.0 || now - hurtStart >= kFlash) return base;
    const float t = 1.0f - static_cast<float>((now - hurtStart) / kFlash);  // 1 -> 0
    const float mul = 1.0f + 1.6f * t;  // up to ~2.6x at the moment of impact, easing back
    return Vec3{base.x * mul, base.y * mul, base.z * mul};
}

