                        skillParticles_.setEmitter(base);  // impact flash at the base
                        Particle f;
                        f.r = 0.88f; f.g = 0.94f; f.b = 1.0f; f.a = 0.9f; f.da = -3.6f;
                        f.size = 0.5f; f.growth = 1.2f; f.life = 0.25f; f.fxTex = glow;
                        skillParticles_.emit(f);
